function parseMatrix(text){ var lines=String(text).trim().split(/\n/).filter(function(l){return l.trim().length;});
  var rows=[]; for(var i=0;i<lines.length;i++){ var vals=lines[i].trim().split(/[\s,;]+/).filter(function(x){return x.length;}).map(function(x){return parseFloat(x);});
    if(vals.some(function(v){return isNaN(v);})) return {error:'第 '+(i+1)+' 行含非数字'}; rows.push(vals); }
  if(!rows.length) return {error:'矩阵为空'};
  var c=rows[0].length; for(var j=1;j<rows.length;j++){ if(rows[j].length!==c) return {error:'各行列数不一致'}; }
  return {m:rows};
}
function add(a,b){ if(a.length!==b.length||a[0].length!==b[0].length) return {error:'维度不匹配'};
  return a.map(function(r,i){return r.map(function(v,j){return v+b[i][j];});}); }
function sub(a,b){ if(a.length!==b.length||a[0].length!==b[0].length) return {error:'维度不匹配'};
  return a.map(function(r,i){return r.map(function(v,j){return v-b[i][j];});}); }
function mul(a,b){ if(a[0].length!==b.length) return {error:'A列数须等于B行数'};
  var out=[]; for(var i=0;i<a.length;i++){ out[i]=[]; for(var j=0;j<b[0].length;j++){ var s=0; for(var k=0;k<b.length;k++) s+=a[i][k]*b[k][j]; out[i][j]=s; } } return out; }
function transpose(a){ var out=[]; for(var j=0;j<a[0].length;j++){ out[j]=[]; for(var i=0;i<a.length;i++) out[j][i]=a[i][j]; } return out; }
function det(a){ var n=a.length; if(n!==a[0].length) return {error:'须为方阵'};
  var M=a.map(function(r){return r.slice();}); var d=1;
  for(var i=0;i<n;i++){ var p=i; for(var r=i+1;r<n;r++) if(Math.abs(M[r][i])>Math.abs(M[p][i])) p=r;
    if(p!==i){ var t=M[p];M[p]=M[i];M[i]=t; d=-d; }
    if(Math.abs(M[i][i])<1e-12) return 0;
    for(var r2=i+1;r2<n;r2++){ var f=M[r2][i]/M[i][i]; for(var c=i;c<n;c++) M[r2][c]-=f*M[i][c]; } }
  for(var k=0;k<n;k++) d*=M[k][k]; return d; }
function inverse(a){ var n=a.length; if(n!==a[0].length) return {error:'须为方阵'};
  var D=det(a); if(typeof D==='object') return D; if(Math.abs(D)<1e-12) return {error:'行列式为 0，不可逆'};
  var M=a.map(function(r,i){return r.slice().concat(identityRow(n,i));});
  for(var i=0;i<n;i++){ var p=i; for(var r=i+1;r<n;r++) if(Math.abs(M[r][i])>Math.abs(M[p][i])) p=r;
    var t=M[p];M[p]=M[i];M[i]=t; var iv=1/M[i][i]; for(var c=0;c<2*n;c++) M[i][c]*=iv;
    for(var r2=0;r2<n;r2++){ if(r2===i) continue; var f=M[r2][i]; for(var c2=0;c2<2*n;c2++) M[r2][c2]-=f*M[i][c2]; } }
  return M.map(function(r){return r.slice(n);}); }
function identityRow(n,i){ var r=[]; for(var j=0;j<n;j++) r[j]=(j===i)?1:0; return r; }
var EXPORTS={parseMatrix:parseMatrix,add:add,sub:sub,mul:mul,transpose:transpose,det:det,inverse:inverse};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.MatrixCalcForgePure = EXPORTS; }
